/**
 * Laya Feed Control - Tokenizer and Sequence Construction
 * Mirrors Laya's common.py build_sequence and render_options
 */

import { LayaQuestion, QType } from '../types';

export const QTYPES: Record<QType, number> = {
  choice: 0,
  score: 1,
  noul: 2,
};

export const SPECIAL_TOKENS = {
  PAD: 0,
  BOS: 1, // <bos> / [CLS]
  EOS: 2, // <eos> / [SEP]
  UNK: 3, // <unk>
  MASK: 4, // <mask> / [MASK]
};

export interface TokenizerLike {
  bosTokenId: number;
  eosTokenId: number;
  maskTokenId: number;
  padTokenId: number;
  encode(text: string): number[];
  decode(tokens: number[]): string;
}

export function serializeState(state: string | Record<string, unknown> | unknown[]): string {
  if (typeof state === 'string') {
    return state;
  }
  return JSON.stringify(state);
}

export function renderCriterion(value: unknown): string {
  if (typeof value === 'string') {
    return value;
  }
  if (value === null || value === undefined) {
    return '';
  }
  return JSON.stringify(value);
}

export function renderOptions(q: { t: QType; crit?: any }): string[] {
  const { t, crit } = q;
  if (t === 'choice') {
    if (!crit) return [];
    return Object.entries(crit).map(([k, v]) => {
      if (v === null || v === undefined || v === '') {
        return k;
      }
      return `${k}: ${renderCriterion(v)}`;
    });
  }
  if (t === 'score') {
    const list = Array.isArray(crit) ? crit : [];
    return list.map((c, i) => `level ${i}: ${renderCriterion(c)}`);
  }
  // noul
  const falseCrit = crit?.false;
  const trueCrit = crit?.true;
  return [
    'false: ' + (falseCrit ? renderCriterion(falseCrit) : 'no, the statement does not hold'),
    'true: ' + (trueCrit ? renderCriterion(trueCrit) : 'yes, the statement holds'),
  ];
}

/**
 * Fast subword tokenizer with vocabulary cache & fallback hashing
 */
export class FastTokenizer implements TokenizerLike {
  public bosTokenId = SPECIAL_TOKENS.BOS;
  public eosTokenId = SPECIAL_TOKENS.EOS;
  public maskTokenId = SPECIAL_TOKENS.MASK;
  public padTokenId = SPECIAL_TOKENS.PAD;

  private vocab: Map<string, number> = new Map();
  private reverseVocab: Map<number, string> = new Map();

  constructor(customVocab?: Record<string, number>) {
    this.vocab.set('<pad>', SPECIAL_TOKENS.PAD);
    this.vocab.set('<bos>', SPECIAL_TOKENS.BOS);
    this.vocab.set('<eos>', SPECIAL_TOKENS.EOS);
    this.vocab.set('<unk>', SPECIAL_TOKENS.UNK);
    this.vocab.set('<mask>', SPECIAL_TOKENS.MASK);

    if (customVocab) {
      for (const [k, v] of Object.entries(customVocab)) {
        this.vocab.set(k, v);
        this.reverseVocab.set(v, k);
      }
    }
  }

  public encode(text: string): number[] {
    const tokens: number[] = [];
    const normalized = text.normalize('NFKC').trim();
    if (!normalized) return [];

    // Split on whitespace and punctuation while retaining characters
    const words = normalized.split(/(\s+|[^\w\s])/).filter((w) => w.trim().length > 0);

    for (const w of words) {
      const lower = w.toLowerCase();
      if (this.vocab.has(lower)) {
        tokens.push(this.vocab.get(lower)!);
      } else {
        // Deterministic subword hashing into mmBERT vocab range (5..250000)
        let hash = 0;
        for (let i = 0; i < lower.length; i++) {
          hash = (hash << 5) - hash + lower.charCodeAt(i);
          hash |= 0;
        }
        const tokenId = 5 + (Math.abs(hash) % 249000);
        tokens.push(tokenId);
      }
    }

    return tokens;
  }

  public decode(tokenIds: number[]): string {
    return tokenIds
      .map((id) => this.reverseVocab.get(id) || `[token_${id}]`)
      .join(' ');
  }
}

/**
 * Constructs Laya sequence:
 * [CLS] <type> question: <instructions> [SEP] [MASK] opt0 [MASK] opt1 ... [SEP] state [SEP]
 */
export function buildSequence(
  tok: TokenizerLike,
  state: string | Record<string, unknown> | unknown[],
  q: { t: QType; ins: string; crit?: any },
  maxLen = 512,
  headMaxLen = 192,
  truncateLeft = false
): { ids: number[]; markers: number[] } {
  const opts = renderOptions(q);
  const cleanIns = q.ins.replace(/<mask>/g, ' ');
  const headPrefix = `${q.t} question: ${cleanIns}`;
  let headIds = tok.encode(headPrefix);

  const optIds: number[][] = [];
  for (const opt of opts) {
    const cleanOpt = opt.replace(/<mask>/g, ' ');
    const encodedOpt = tok.encode(' ' + cleanOpt).slice(0, 48);
    optIds.push([tok.maskTokenId, ...encodedOpt]);
  }

  let optBudget = headMaxLen - optIds.reduce((sum, o) => sum + o.length, 0);
  if (optBudget < 16) {
    const per = Math.max(4, Math.floor((headMaxLen - 16) / Math.max(1, optIds.length)));
    for (let i = 0; i < optIds.length; i++) {
      optIds[i] = optIds[i].slice(0, per);
    }
    optBudget = headMaxLen - optIds.reduce((sum, o) => sum + o.length, 0);
  }

  headIds = headIds.slice(0, Math.max(8, optBudget));

  // Construct [CLS] head [SEP]
  const ids: number[] = [tok.bosTokenId, ...headIds, tok.eosTokenId];
  const markers: number[] = [];

  for (const opt of optIds) {
    markers.push(ids.length);
    ids.push(...opt);
  }

  ids.push(tok.eosTokenId);

  // Append state
  const room = Math.max(0, maxLen - ids.length - 1);
  const serialized = serializeState(state).replace(/<mask>/g, ' ');
  let st = tok.encode(serialized);
  if (truncateLeft) {
    st = st.slice(-room);
  } else {
    st = st.slice(0, room);
  }

  ids.push(...st, tok.eosTokenId);

  const finalIds = ids.slice(0, maxLen);
  const finalMarkers = markers.filter((m) => m < maxLen);

  return { ids: finalIds, markers: finalMarkers };
}
