/**
 * Laya Feed Control - Dedicated Inference Web Worker
 * Runs ONNX Runtime Web on WebGPU / WASM
 */

import { LayaEngine } from '../engine/laya-model';
import { OnnxSessionManager } from '../engine/onnx-session';

const engine = new LayaEngine();
const sessionManager = new OnnxSessionManager();

self.onmessage = async (e: MessageEvent) => {
  const { id, type, payload } = e.data;

  if (type === 'STATUS') {
    self.postMessage({ id, result: sessionManager.getStatus() });
    return;
  }

  if (type === 'LOAD_MODEL') {
    try {
      const ok = await sessionManager.loadModel(
        payload.modelUrl,
        payload.preference || 'prefer_webgpu'
      );
      if (ok) {
        engine.setSession(sessionManager.getSession());
      }
      self.postMessage({ id, result: { success: ok } });
    } catch (err: any) {
      self.postMessage({ id, error: err.message || 'Model load failed' });
    }
    return;
  }

  if (type === 'PREDICT') {
    try {
      const { state, questions } = payload;
      const res = await engine.predict(state, questions);
      self.postMessage({ id, result: res });
    } catch (err: any) {
      self.postMessage({ id, error: err.message || 'Inference failed' });
    }
    return;
  }
};
