/**
 * Laya Feed Control - ONNX Runtime WebGPU & WASM Session Manager
 */

import { ComputeBackend } from '../types';

export interface SessionStatus {
  isLoaded: boolean;
  backend: 'webgpu' | 'wasm' | 'none';
  modelId: string;
  error?: string;
  downloadProgress?: number; // 0..100
}

export class OnnxSessionManager {
  private ort: any = null;
  private session: any = null;
  private backend: 'webgpu' | 'wasm' | 'none' = 'none';
  private downloadProgress = 0;
  private statusListeners: Array<(status: SessionStatus) => void> = [];

  constructor() {
    this.initOrt();
  }

  private async initOrt(): Promise<void> {
    try {
      // Dynamically import or load onnxruntime-web in browser/worker context
      if (typeof window !== 'undefined' && (window as any).ort) {
        this.ort = (window as any).ort;
      } else if (typeof self !== 'undefined' && (self as any).ort) {
        this.ort = (self as any).ort;
      } else {
        this.ort = await import('onnxruntime-web');
      }

      // Configure WASM paths
      if (this.ort?.env?.wasm) {
        this.ort.env.wasm.numThreads = 2;
        this.ort.env.wasm.simd = true;
      }
    } catch (err) {
      console.warn('[Laya] ONNX Runtime Web init warning:', err);
    }
  }

  public onStatusChange(listener: (status: SessionStatus) => void): () => void {
    this.statusListeners.push(listener);
    listener(this.getStatus());
    return () => {
      this.statusListeners = this.statusListeners.filter((l) => l !== listener);
    };
  }

  private notify(): void {
    const status = this.getStatus();
    for (const listener of this.statusListeners) {
      listener(status);
    }
  }

  public getStatus(): SessionStatus {
    return {
      isLoaded: this.session !== null,
      backend: this.backend,
      modelId: 'mizchi/laya-multilingual-onnx',
      downloadProgress: this.downloadProgress,
    };
  }

  public async hasWebGPUSupport(): Promise<boolean> {
    if (typeof navigator === 'undefined' || !navigator.gpu) {
      return false;
    }
    try {
      const adapter = await navigator.gpu.requestAdapter();
      return adapter !== null;
    } catch {
      return false;
    }
  }

  /**
   * Loads the Laya ONNX model either from IndexedDB cache or network
   */
  public async loadModel(
    modelUrl: string,
    preference: ComputeBackend = 'prefer_webgpu',
    expectedSha256?: string
  ): Promise<boolean> {
    await this.initOrt();

    const canWebGPU = await this.hasWebGPUSupport();
    if (preference === 'require_webgpu' && !canWebGPU) {
      this.backend = 'none';
      this.notify();
      throw new Error('WebGPU is required by settings, but no compatible WebGPU adapter was found.');
    }

    const executionProviders = canWebGPU
      ? ['webgpu', 'wasm']
      : preference === 'require_webgpu'
      ? []
      : ['wasm'];

    if (executionProviders.length === 0) {
      throw new Error('No valid execution provider available.');
    }

    try {
      const modelBuffer = await this.fetchWithCache(modelUrl, expectedSha256);

      const sessionOptions: any = {
        executionProviders,
        graphOptimizationLevel: 'basic', // Required for mmBERT WebGPU graph
      };

      this.session = await this.ort.InferenceSession.create(modelBuffer, sessionOptions);
      this.backend = canWebGPU ? 'webgpu' : 'wasm';
      this.notify();
      return true;
    } catch (err: any) {
      console.error('[Laya] Failed to create ONNX session:', err);
      if (canWebGPU && preference === 'prefer_webgpu') {
        console.warn('[Laya] Retrying with CPU/WASM fallback...');
        try {
          const modelBuffer = await this.fetchWithCache(modelUrl, expectedSha256);
          this.session = await this.ort.InferenceSession.create(modelBuffer, {
            executionProviders: ['wasm'],
            graphOptimizationLevel: 'basic',
          });
          this.backend = 'wasm';
          this.notify();
          return true;
        } catch (fallbackErr) {
          this.session = null;
          this.backend = 'none';
          this.notify();
          throw fallbackErr;
        }
      }
      this.session = null;
      this.backend = 'none';
      this.notify();
      throw err;
    }
  }

  public getSession(): any {
    return this.session;
  }

  public dispose(): void {
    if (this.session) {
      try {
        this.session.release();
      } catch {}
      this.session = null;
    }
    this.backend = 'none';
    this.notify();
  }

  private async fetchWithCache(url: string, expectedSha256?: string): Promise<ArrayBuffer> {
    // Check CacheStorage first
    if (typeof caches !== 'undefined') {
      try {
        const cache = await caches.open('laya-models-v1');
        const cachedRes = await cache.match(url);
        if (cachedRes) {
          const buf = await cachedRes.arrayBuffer();
          this.downloadProgress = 100;
          this.notify();
          return buf;
        }
      } catch (e) {
        console.warn('[Laya] CacheStorage check failed:', e);
      }
    }

    // Stream download with progress tracking
    const response = await fetch(url);
    if (!response.ok) {
      throw new Error(`Model download failed: HTTP ${response.status}`);
    }

    const contentLength = Number(response.headers.get('Content-Length')) || 0;
    if (!response.body || contentLength === 0) {
      const buf = await response.arrayBuffer();
      this.downloadProgress = 100;
      this.notify();
      return buf;
    }

    const reader = response.body.getReader();
    const chunks: Uint8Array[] = [];
    let receivedBytes = 0;

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      if (value) {
        chunks.push(value);
        receivedBytes += value.length;
        if (contentLength > 0) {
          this.downloadProgress = Math.round((receivedBytes / contentLength) * 100);
          this.notify();
        }
      }
    }

    // Combine chunks
    const fullBuffer = new Uint8Array(receivedBytes);
    let offset = 0;
    for (const chunk of chunks) {
      fullBuffer.set(chunk, offset);
      offset += chunk.length;
    }

    // Cache the result
    if (typeof caches !== 'undefined') {
      try {
        const cache = await caches.open('laya-models-v1');
        await cache.put(url, new Response(fullBuffer.buffer));
      } catch (e) {
        console.warn('[Laya] Cache save failed:', e);
      }
    }

    return fullBuffer.buffer;
  }
}
